//! The Tellshot editor: a Slint shell over `tellshot-core`.
//!
//! * `ui/` holds layout and interaction only, compiled ahead of time by `slint-build`.
//! * [`session`] owns all state and decisions (tools, gestures, styles, undo, files), with no
//!   Slint types, so it is unit-testable without a window.
//! * `bind` connects the two: UI callbacks call into the session, and a snapshot of the session
//!   is pushed back into UI properties after every change.

mod bind;
pub mod session;

/// Code generated from `ui/app.slint`.
#[expect(
    clippy::all,
    clippy::restriction,
    unreachable_pub,
    missing_docs,
    missing_debug_implementations,
    unnameable_types,
    single_use_lifetimes,
    trivial_casts,
    trivial_numeric_casts,
    unused_qualifications,
    let_underscore_drop,
    reason = "generated by slint-build; not our code to lint"
)]
mod ui {
    slint::include_modules!();
}

pub use bind::{attach, launch, refresh};
pub use ui::{AppWindow, Theme};
